from pathlib import Path
import html,json
R=Path(__file__).resolve().parent; pages=[]
def esc(s): return html.escape(s)
def add(title,sub,body,tag='دليل التشغيل',image=None,steps=None,tip=None):
    content=''
    if image: content+=f'<figure><img src="assets/{image}.png"><figcaption>واجهة لوحة الأكاديميات • بيانات تدريبية توضيحية • قد تختلف الحقول بحسب الصلاحيات والإصدار</figcaption></figure>'
    if steps:content+='<ol class="steps">'+''.join(f'<li><span>{i+1:02}</span><div>{x}</div></li>' for i,x in enumerate(steps))+'</ol>'
    content+=body
    if tip:content+=f'<aside><b>قبل الانتقال</b><p>{tip}</p></aside>'
    pages.append(dict(title=title,sub=sub,tag=tag,content=content))
def cards(items):return '<div class="cards">'+''.join(f'<article><h3>{a}</h3><p>{b}</p></article>' for a,b in items)+'</div>'
def table(head,rows):return '<table><thead><tr>'+''.join('<th>'+v+'</th>' for v in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table>'
def flow(items):return '<div class="flow">'+''.join('<div><b>'+str(i+1).zfill(2)+'</b><span>'+s+'</span></div>' for i,s in enumerate(items))+'</div>'
add('دليلك إلى تشغيل الأكاديمية','من أول تسجيل دخول إلى أول حصة وتحصيل', '<div class="cover-main"><span class="pill">نسخة الأكاديميات • دولة قطر</span><h1>ابدأ بثقة.<br>شغّل أكاديميتك<br><em>بخطوات واضحة.</em></h1><p>دليل التهيئة والاستخدام<br>لوحة الشركاء • Hagzz Partner للمالك وولي الأمر • Hagzz لاختيار التدريبات</p><div class="cover-line"></div><span>ACADEMY ONBOARDING & USER GUIDE</span></div><div class="cover-bottom"><b>Hagzz</b><p>الإصدار 1.0 • 23 أكتوبر 2026<br>دليل عربي مصوّر | للاستخدام الرقمي والطباعة</p></div>',tag='HAGZZ / QATAR')
add('كيف تستخدم هذا الدليل؟','ابدأ بالتهيئة، ثم اتبع مسار دورك.',cards([('للمالك ومسؤول التشغيل','اقرأ صفحات الإعداد والتسجيل والتحصيل، ثم نفّذ قائمة الجاهزية قبل استقبال اللاعبين.'),('لولي الأمر عبر Hagzz Partner','ابدأ بمسار حساب ولي الأمر، واطلب من الأكاديمية تفعيل الوصول وربط بيانات اللاعب.'),('للعميل واللاعب أو ولي الأمر','استخدم Hagzz لاختيار التدريبات، واستخدم حساب ولي الأمر في Hagzz Partner للمتابعة بعد تفعيله.'),('عن هذه النسخة','تطبيقان بمسارات واضحة: Hagzz Partner بحساب للمالك وحساب مستقل لولي الأمر، وHagzz لاختيار التدريبات. هذا الجزء للأكاديميات فقط. للجيم والمراكز الصحية والملاعب والمرافق أدلة مستقلة لاحقة.')])+ '<h3>طريقة قراءة صفحات الخطوات</h3><p>ستجد صورة الواجهة، ثم خطوات مرقّمة، ثم نقطة تحقق قبل الانتقال. الأسماء والأسعار الظاهرة أمثلة تدريبية وليست عروضًا تجارية.</p><aside><b>نطاق العرض في قطر</b><p>منحة من Hagzz وواحة قطر للعلوم والتكنولوجيا لدعم التحول الرقمي في القطاع الرياضي. تشمل خصومات وشهورًا مجانية لجميع الأكاديميات دون تمييز بحسب الحجم، وفق العرض المعتمد لكل أكاديمية.</p></aside>')
add('المحتويات','مرجع سريع للعودة إلى الخطوة المطلوبة.', '<div id="toc"></div><p class="small">روابط المحتويات داخل ملف PDF قابلة للنقر. تتوفر روابط التثبيت والدخول في الصفحات المخصصة لها.</p>')
add('تطبيقان… وتجربة متكاملة','اختر التطبيق والحساب المناسبين قبل البدء.',cards([('لوحة الشركاء على الويب','المساحة الأساسية لإعداد الأكاديمية وإدارة البرامج واللاعبين والاشتراكات والتحصيل.'),('Hagzz Partner / حساب المالك','حساب مخصص للمالك لإدارة ومتابعة الأكاديمية من التطبيق، بحسب ما يتاح لحسابه.'),('Hagzz Partner / حساب ولي الأمر','حساب مستقل عن المالك. يُفعّل المسار الخاص بولي الأمر بالتنسيق مع الأكاديمية لمتابعة ما يُتاح له من بيانات.'),('Hagzz / تطبيق العملاء','التطبيق المخصص لاكتشاف الأكاديميات واختيار التدريبات ومراجعة تفاصيلها وإجراءات التسجيل المتاحة.')])+ '<h3>حسابات منفصلة وصلاحيات واضحة</h3><p>لا يستخدم ولي الأمر بيانات دخول المالك. كما أن حساب تطبيق العملاء لا يُفترض أنه يمنح تلقائيًا دخولًا إلى Hagzz Partner. اطلب تفعيل الحساب الصحيح وربط بيانات اللاعب عبر الأكاديمية عند الحاجة.</p><aside><b>قاعدة البداية</b><p>للإدارة والمتابعة: Hagzz Partner. لاختيار التدريبات: Hagzz. روابط التفعيل الخاصة بـ Hagzz Partner تؤخذ من فريق التهيئة.</p></aside>')
add('جهّز بياناتك قبل البدء','تجهيز البيانات مرة واحدة يجعل الإعداد أسرع.',table(['ما المطلوب؟','من يجهّزه؟','ما الذي تراجعه؟'],[['اسم الأكاديمية وشعارها','المالك','الاسم بالعربية والإنجليزية وحق استخدام الشعار'],['الفروع ومواقع التدريب','مسؤول التشغيل','الدولة: قطر، المدينة، العنوان وبيانات الوصول'],['المدربون والرياضات','مسؤول التشغيل','الاسم والهاتف والرياضة وتفاصيل التكليف'],['البرامج والمواعيد','الإدارة والمدرب','المستوى والفئة والسعة والأيام والتوقيت'],['اللاعب وولي الأمر','التسجيل','صحة التواصل والمعلومات الصحية اللازمة'],['الاشتراكات والتحصيل','المسؤول المالي','السعر والمدة وطريقة الدفع وصلاحية التحصيل']])+ '<h3>بيئة العمل</h3><p>استخدم متصفحًا حديثًا واتصالًا مستقرًا. لا تحتاج لوحة الشركاء إلى تثبيت برنامج على الكمبيوتر. خصص حسابًا مستقلًا لكل موظف، ولا تتشارك كلمات المرور.</p>',tip='اعتمد العملة والتسعير الخاصين بأكاديميتك قبل إدخال المدفوعات. أمثلة هذا الدليل ليست أسعارًا مقترحة للعملاء.')
add('افتح لوحة الشركاء وسجّل الدخول','خطوة 01 / دخول المالك أو مسؤول التشغيل','<p class="link"><a href="https://partner.hagzz.el7lm.com/partner/login">partner.hagzz.el7lm.com/partner/login</a></p>',image='login',steps=['افتح الرابط من المتصفح وتأكد من أن العنوان يبدأ بـ <span dir="ltr">https://</span>.','أدخل البريد الإلكتروني وكلمة المرور اللذين خُصصا لحسابك، ثم اضغط تسجيل الدخول.','تأكد من اسم الأكاديمية الظاهر بعد الدخول. إذا لم تُفعّل بياناتك، تواصل مع مسؤول التهيئة.'],tip='لا تستخدم كلمة مرور تجريبية أو بيانات تخص أكاديمية أخرى. تسجيل دخول لوحة الشركاء مستقل عن رقم هاتف حساب العميل.')
add('تعرّف على رحلة التشغيل','خطوة 02 / القائمة مرتّبة حسب مراحل العمل','',image='guide',steps=['ابدأ بقسم «تجهيز النشاط» لإعداد مواقع التدريب والمدربين والبرامج.','انتقل إلى «التسجيل والاشتراكات» لإنشاء اللاعبين والمجموعات والاشتراكات.','استخدم «التشغيل اليومي» للحضور، و«المالية والتحصيل» للدفعات والتقارير.'],tip='إذا لم تظهر صفحة، راجع نوع حساب الأكاديمية وصلاحيات المستخدم مع المالك. لا تعالج نقص الصلاحيات بمشاركة حساب المالك.')
add('راجع ملف الأكاديمية','خطوة 03 / هوية صحيحة وبيانات اتصال واضحة','',image='profile',steps=['افتح صفحة الملف أو إعدادات الأكاديمية من الحساب.','راجع الاسم والشعار وبيانات التواصل والرياضات المتاحة؛ حدّث الحقول التي تملك صلاحية تعديلها.','احفظ التغييرات، ثم افتح الصفحة مرة أخرى للتأكد من ظهور البيانات الصحيحة.'],tip='ظهور الهوية في لوحة الشركاء لا يكفي وحده لإثبات نشر الأكاديمية في تطبيق العملاء. افحص العرض على التطبيق بصورة مستقلة.')
add('أضف موقع التدريب أولًا','خطوة 04 / الأساس الذي سترتبط به البرامج والحصص','',image='location',steps=['من «تجهيز النشاط» افتح «مواقع التدريب» ثم إضافة موقع.','اكتب اسم الموقع والعنوان بالعربية والإنجليزية. اختر قطر ثم المدينة والمنطقة الصحيحتين من الخيارات المتاحة.','راجع حالة التفعيل وملكية الموقع بحسب بياناتك الفعلية، ثم احفظ.'],tip='تأكد أن الموقع يظهر في قائمة المواقع، وأن وصف الوصول واضح لولي الأمر. لا تضع عنوانًا تجريبيًا في حساب الإنتاج.')
add('أضف المدرب واربط رياضته','خطوة 05 / بيانات تشغيل واضحة لكل مدرب','',image='coach',steps=['افتح «المدربون» ثم إضافة مدرب، وأدخل الاسم والهاتف والرياضة.','اختر طريقة احتساب المستحقات وقيمتها إذا كان حسابك يستخدم هذه الحقول، بناءً على الاتفاق الفعلي.','راجع حالة التفعيل ثم احفظ. استخدم حساب فريق مستقلًا إذا كان المدرب يحتاج إلى الدخول.'],tip='إضافة سجل مدرب لا تعني تلقائيًا إنشاء حساب دخول له. راجع قسم الفريق والصلاحيات قبل إرسال بيانات الدخول.')
add('أنشئ برنامج التدريب','خطوة 06 / البرنامج يصف ما تقدمه الأكاديمية','',image='training',steps=['افتح «التدريبات» ثم إضافة تدريب؛ اكتب اسم البرنامج ووصفه والرياضة.','اختر المدرب والموقع، ثم الفئة والمستوى والسعة وعدد الحصص والأيام والتوقيت.','راجع السعر والخصم إن وجد، ثم خيار إنشاء الحصص تلقائيًا قبل الحفظ.'],tip='مثال تعليمي فقط: أساسيات كرة القدم، 8 حصص، يومان أسبوعيًا. استخدم جدولك وسعرك المعتمدين، ولا تكرر إنشاء حصص البرنامج.')
add('راجع الحصص قبل التسجيل','خطوة 07 / البرنامج ليس هو الحصة','',image='classes',steps=['افتح قائمة الحصص بعد حفظ البرنامج.','راجع التواريخ والأيام والموقع والمدرب ووقت البداية والنهاية. اعتمد توقيت قطر عند إعلان المواعيد.','صحح أي تعارض أو حصة مكررة قبل إرسال الجدول للاعبين وأولياء الأمور.'],tip='البرنامج هو العرض التدريبي؛ الحصة موعد محدد لتنفيذه؛ المجموعة هي اللاعبون المشاركون في التدريب.')
add('أنشئ ملف اللاعب وولي الأمر','خطوة 08 / ملف واحد واضح بدل السجلات المتكررة','',image='student',steps=['من «ملفات الطلاب» أضف اللاعب: الاسم والهاتف وتاريخ الميلاد والبيانات المطلوبة.','أكمل اسم ولي الأمر ورقم تواصله وصلة القرابة، وراجع المعلومات الصحية الضرورية للتدريب.','احفظ الملف، ثم ابحث عنه في القائمة للتأكد من عدم وجود نسخة مكررة.'],tip='اجمع البيانات اللازمة فقط وبموافقة مناسبة. ملف اللاعب داخل الأكاديمية لا يُنشئ حسابًا تلقائيًا في تطبيق العملاء.')
add('كوّن المجموعة وأضف أعضاءها','خطوة 09 / المجموعة تربط البرنامج باللاعبين','',image='group',steps=['افتح «المجموعات التدريبية» ثم إضافة مجموعة. سمّها باسم واضح للفئة أو المستوى.','اربط البرنامج والمدرب والرياضة، وحدد أيامها وتوقيتها وسعتها.','اختر اللاعبين ضمن أعضاء المجموعة ثم احفظ، وراجع قائمة الأعضاء.'],tip='وجود اشتراك للاعب لا يغني عن التأكد من إضافته إلى المجموعة. قائمة الأعضاء هي نقطة مهمة لظهوره في كشف الحضور.')
add('سجّل اشتراك اللاعب','خطوة 10 / مدة الاشتراك وقيمته وحالته','',image='subscription',steps=['افتح «الاشتراكات» ثم إضافة اشتراك؛ اختر اللاعب والمجموعة.','حدد تاريخ البداية والنهاية والمبلغ المتفق عليه وحالة الاشتراك، ثم احفظ.','راجع بيانات الاشتراك قبل التحصيل. سجّل كل دفعة فعلية كسجل دفع منفصل.'],tip='قيمة الاشتراك ليست دفعة محصلة. لا تعتبر الحساب مسددًا إلا بعد تسجيل دفعات حقيقية ومراجعة الرصيد.')
add('حصّل المبلغ وسجّل الدفعة','خطوة 11 / إثبات كل حركة مالية','',image='payment',steps=['افتح الاشتراك ثم قسم إضافة دفعة. أدخل المبلغ وتاريخ التحصيل وطريقة الدفع.','اكتب مرجع الإيصال أو العملية عند الحاجة، ثم احفظ مرة واحدة وانتظر تأكيد النتيجة.','ارجع إلى الاشتراك وراجع المدفوع والمتبقي قبل إرسال الإيصال.'],tip='مثال حسابي بالريال القطري: اشتراك 800 ر.ق، دفعة 500 ر.ق، متبقٍ 300 ر.ق. المثال للتوضيح فقط، وليس تسعيرًا للخدمة.')
add('راجع الرصيد وأصدر المستند','خطوة 12 / تحصيل واضح للموظف وولي الأمر','',image='subscriptions',steps=['ابحث عن اشتراك اللاعب وراجع الإجمالي والمدفوع والمتبقي وحالة السداد.','استخدم خيار عرض أو طباعة الفاتورة المتاح في حسابك، وراجع الاسم والمبالغ والتواريخ.','سلّم المستند للعميل بالطريقة المعتمدة في الأكاديمية، واحتفظ بمرجع العملية.'],tip='إذا خصمت دفعة من وسيلة الدفع ولم تظهر في النظام، تحقق من مرجعها قبل محاولة التحصيل مجددًا. لا تصدر تأكيد سداد اعتمادًا على رسالة شفوية.')
add('أنشئ جلسة الحضور','خطوة 13 / جلسة للمجموعة في يوم التدريب','',image='attendance',steps=['من «التشغيل اليومي» افتح الحضور ثم إنشاء جلسة.','اختر المجموعة وتاريخ التدريب ووقت البداية والنهاية، ثم احفظ.','افتح كشف الجلسة وتأكد من أسماء اللاعبين قبل بدء تسجيل الحالات.'],tip='إذا كان الكشف ناقصًا، راجع عضوية المجموعة أولًا. تأكد من أنك تعمل على تاريخ الحصة والمجموعة الصحيحين.')
add('سجّل الحضور أو امسح البطاقة','خطوة 14 / مراجعة النتيجة أهم من عملية المسح','',image='scanner',steps=['للتسجيل اليدوي افتح كشف الجلسة، وحدد حالة اللاعب ووقت دخوله عند الحاجة، ثم احفظ.','عند استخدام الماسح، افتح صفحة المسح واسمح للكاميرا عند طلبها، وحدد سياق الحضور المطلوب إن ظهر.','امسح بطاقة اللاعب، ثم اقرأ نتيجة العملية وتحقق من الاسم والجلسة. استخدم التسجيل اليدوي إذا تعذرت الكاميرا.'],tip='بطاقة اللاعب ليست إذنًا بالتصوير أو المشاركة العامة. إذا رُفض الرمز، راجع صلاحية البطاقة وملف اللاعب بدل تسجيل لاعب آخر بالخطأ.')
add('أغلق اليوم بمراجعة سريعة','خطوة 15 / حضور صحيح وتحويلات مالية قابلة للمراجعة','',image='report',steps=['راجع جلسات اليوم وأكمل حالات الحضور الناقصة.','راجع التحصيل والمتأخرات، ثم سجل المصروفات الفعلية من القسم المخصص لها.','افتح التقرير المالي وحدد الفترة المناسبة؛ طابقه مع سجلات الدفع والإيصالات.'],tip='صلاحيات عرض التقارير والتحصيل يجب أن تقتصر على المكلفين بها. راجع الفترة المحددة في التقرير قبل مقارنة الأرقام.')
add('امنح الفريق الصلاحية المناسبة','مسار المالك والإدارة / إعداد الوصول','',image='team',steps=['من «الفريق والإعدادات» أضف موظفًا بحساب مستقل وبيانات صحيحة.','حدد الفروع والرياضات والصلاحيات المناسبة لعمله. لا تمنح التحصيل أو التقارير المالية لمن لا يحتاجهما.','اختبر الدخول بحساب الموظف وتأكد من الصفحات المتاحة. اطلب رابط Hagzz Partner المعتمد من فريق Hagzz إذا كنت ستستخدمه.'],tip='رابط Hagzz Partner وتفعيل حساب المالك تؤكدهما جهة التهيئة. لوحة الويب هي مرجع الخطوات المصوّرة في هذا الدليل؛ لا يُفترض تطابق شاشاتها مع تطبيق الهاتف.')
add('ثبّت Hagzz Partner واختر حسابك','تطبيق واحد للمالك وولي الأمر… بحسابين مستقلين.', '<div class="phoneflow"><div class="phone"><small>Hagzz Partner</small><h3>حساب المالك</h3><div class="mockbutton">وصول الإدارة</div><p>بيانات حساب المالك<br>الصلاحيات المخصصة له</p></div><div class="phone"><small>Hagzz Partner</small><h3>حساب ولي الأمر</h3><div class="mockbutton">وصول ولي الأمر</div><p>بيانات حساب مستقلة<br>ربط اللاعب مع الأكاديمية</p></div></div><p class="small">رسم إرشادي يوضح فصل الحسابات؛ ليس صورة لشاشة الدخول ولا يعني وجود زرين بهذا الشكل داخل التطبيق.</p>',steps=['اطلب رابط تنزيل Hagzz Partner المعتمد عبر <a href="https://wa.me/97470542458">فريق التهيئة على واتساب</a>، وحدد أنك مالك أكاديمية أو ولي أمر.','افتح الرابط على هاتفك وثبّت النسخة التي يعتمدها الفريق لنظام جهازك، ثم افتح التطبيق.','استخدم بيانات الحساب المخصص لدورك واتبع تعليمات التفعيل. لا تستخدم بيانات المالك للدخول كولي أمر.'],tip='للحصول على نسخة Hagzz Partner المناسبة لهاتفك، استخدم رابط التواصل أعلاه. يرسل فريق التهيئة رابط التثبيت وبيانات التفعيل.')
add('ابدأ المتابعة كولي أمر','Hagzz Partner / حساب ولي الأمر',flow(['طلب تفعيل الحساب','الدخول بالبيانات الخاصة','التحقق من اللاعب والأكاديمية','مراجعة المعلومات المتاحة'])+cards([('جهّز طلب التفعيل','زود الأكاديمية باسم اللاعب ورقم تواصلك الصحيح، واطلب حساب ولي الأمر المخصص لك. لا ترسل رمز التحقق لأي شخص.'),('تحقق من بيانات اللاعب','بعد الدخول تأكد من أنك ترى الأكاديمية واللاعب الصحيحين في البيانات التي تظهر لحسابك. إذا لم يظهر الربط، تواصل مع التسجيل.'),('راجع ما يتيحه الحساب','اطلع على المواعيد أو الاشتراكات أو المتابعة التي تعرضها نسختك وحسابك. لا تفترض ظهور كل بيانات لوحة الإدارة.'),('صحح الاختلاف من مصدره','عند اختلاف موعد أو رصيد، ارجع إلى الأكاديمية وقدم مرجع الاشتراك أو الإيصال. لا تنشئ ملف لاعب جديدًا لمعالجة اختلاف العرض.')])+ '<aside><b>هل تريد اختيار تدريب جديد؟</b><p>انتقل إلى تطبيق Hagzz للعملاء لاستكشاف التدريبات. Hagzz Partner هو مسار المتابعة بحساب ولي الأمر، وتطبيق Hagzz هو مسار اختيار التدريبات.</p></aside>')
add('ثبّت تطبيق العملاء الرسمي','تطبيق Hagzz / اختيار التدريبات', '<div class="install"><img src="assets/hagzz.svg"><h2>Hagzz</h2><p>تطبيق العملاء • اللاعب وولي الأمر</p><a class="button" href="https://play.google.com/store/apps/details?id=com.unlimitedhagzz.hagzz">فتح التطبيق على Google Play</a><p class="small" dir="ltr">com.unlimitedhagzz.hagzz</p></div>',steps=['على Android افتح رابط Google Play أعلاه، وتأكد من اسم التطبيق ثم اضغط «تثبيت» أو «تحديث».','انتظر اكتمال التثبيت ثم افتح التطبيق. النسخة التي يعرضها المتجر هي النسخة المتاحة لجهازك وبلد حسابك.','على iPhone اطلب رابط المتجر المعتمد من فريق Hagzz. لا تثبّت ملفات AAB أو ملفات مرسلة من مصادر غير معتمدة.'],tip='قد تُطرح تحديثات التطبيق على مراحل. لا يعد هذا الدليل تأكيدًا بأن نسخة جديدة قيد المراجعة أصبحت متاحة للعامة.')
add('أنشئ حسابك وفعّل رقمك','مسار اللاعب وولي الأمر / أول استخدام', '<div class="phoneflow"><div class="phone"><small>Hagzz</small><h3>مرحبًا بك</h3><div class="mockbutton">تسجيل الدخول</div><div class="mockbutton outline">إنشاء حساب</div><p>أو الاستمرار كضيف</p></div><div class="phone"><small>تسجيل الدخول</small><h3>رقم الهاتف</h3><div class="mockfield" dir="ltr">+974 •••• ••••</div><div class="mockbutton">متابعة</div><p>استخدم رقمك الصحيح</p></div><div class="phone"><small>التحقق</small><h3>رمز التحقق</h3><div class="mockfield" dir="ltr">• • • •</div><div class="mockbutton">تحقق</div><p>لا تشارك الرمز</p></div></div><p class="small">مخطط بصري للخطوات مستند إلى مسار التطبيق؛ ليس لقطات شاشة فعلية. شكل الواجهة وطول الرمز قد يختلفان.</p>',steps=['اختر إنشاء حساب إذا كنت مستخدمًا جديدًا، أو تسجيل الدخول إذا كان لديك حساب. يمكن التصفح كضيف من شاشة البداية.','اختر مفتاح قطر <span dir="ltr">+974</span> وأدخل رقمك، ثم اتبع شاشة إرسال رمز التحقق.','أدخل الرمز الذي يصلك وأكمل البيانات المطلوبة. إذا لم يصلك، راجع الرقم وانتظر المدة التي تعرضها الشاشة قبل إعادة الطلب.'],tip='ولي الأمر يستخدم بياناته الصحيحة. لا تفترض وجود ملفات متعددة للأبناء أو ربطها تلقائيًا؛ نسّق تسجيل الطفل مع الأكاديمية.')
add('تصفّح البرنامج قبل الالتزام','مسار اللاعب وولي الأمر / البحث والمراجعة', flow(['تحديد البلد والاهتمامات','البحث عن الأكاديمية','فتح تفاصيل البرنامج','مراجعة الشروط مع الأكاديمية'])+cards([('تحقق من هوية الأكاديمية','راجع الاسم والموقع والرياضة، وتأكد أنك اخترت الفرع الصحيح داخل قطر.'),('راجع تفاصيل التدريب','اقرأ العمر والمستوى والمواعيد والسعر وما يشمله، إذا كانت منشورة. استفسر من الأكاديمية عند غياب معلومة.'),('انتبه للمحتوى التجريبي','إذا ظهر وسم «تجريبي» أو «غير قابل للحجز»، فالبيانات للعرض فقط. لا تعتبرها عرضًا مؤكدًا أو تدفع بناءً عليها.'),('الحجز والدفع','استخدم إجراء الحجز أو الدفع فقط عندما يكون متاحًا فعليًا للبرنامج. راجع تأكيد العملية ومرجعها، ولا تفترض توفر الحجز لكل عنصر.')])+ '<aside><b>بعد التسجيل</b><p>راجع الحجوزات أو الجلسات المتاحة لحسابك، واحتفظ بالتأكيد. وللمتابعة عبر Hagzz Partner اطلب تفعيل حساب ولي الأمر من الأكاديمية. الاشتراك المسجل يدويًا في لوحة الأكاديمية لا يضمن ظهوره تلقائيًا في تطبيق العملاء.</p></aside>')
add('قائمة الجاهزية قبل استقبال العملاء','نفّذ تجربة كاملة واحدة مع فريق الأكاديمية.',table(['التحقق','المطلوب قبل الاعتماد'],[['□ هوية الأكاديمية','اسم وشعار وبيانات تواصل صحيحة'],['□ الموقع والمدرب','موقع مفعل ومدرب مرتبط بالرياضة'],['□ البرنامج والحصص','سعر وسعة وأيام وتوقيت بلا تعارض'],['□ اللاعب والمجموعة','ملف صحيح وعضوية مجموعة مؤكدة'],['□ الاشتراك والتحصيل','مدة وقيمة ودفعة اختبار مصرح بها ومراجعة الرصيد'],['□ الحضور','جلسة صحيحة وحالة لاعب محفوظة دون تكرار'],['□ صلاحيات الفريق','دخول مستقل واختبار ما يراه كل دور'],['□ تطبيق العملاء','تثبيت من المتجر واختبار تسجيل الدخول والتصفح'],['□ تجربة ولي الأمر','تأكيد الموعد والموقع ووسيلة التواصل مع الأكاديمية']])+ '<aside><b>اعتماد التشغيل</b><p>ينفّذ المسؤول تجربة على بيانات تدريبية أو حساب مخصص، ثم يعتمد بدء الاستخدام الفعلي. لا تستخدم دفعات حقيقية لمجرد اختبار الواجهة.</p></aside>')
add('حلول سريعة للمشكلات الشائعة','ابدأ بالتحقق البسيط قبل إعادة إدخال البيانات.',table(['المشكلة','ماذا تفعل؟'],[['تعذر الدخول إلى لوحة الشركاء','راجع الرابط والبريد ولغة لوحة المفاتيح. اطلب إعادة تفعيل الوصول من مسؤول الأكاديمية.'],['صفحة غير ظاهرة','راجع الدور والصلاحيات ونوع حساب الأكاديمية مع المالك.'],['الموقع أو المدرب لا يظهر في البرنامج','راجع التفعيل والرياضة والفرع والحقول المطلوبة.'],['اللاعب غير موجود في الحضور','راجع عضوية المجموعة والجلسة وتاريخ التدريب.'],['المبلغ لا يطابق التحصيل','راجع الدفعات المسجلة ومرجع العملية والفترة المختارة، ولا تكرر الدفع مباشرة.'],['تعذّر مسح البطاقة','اسمح للكاميرا وحسّن الإضاءة وتحقق من البطاقة؛ استخدم كشف الحضور اليدوي عند الحاجة.'],['التطبيق لا يفتح أو يطول تحميله','تحقق من الاتصال وحدّثه من المتجر. استخدم إعادة المحاولة إن ظهرت وأرسل تفاصيل العطل للدعم.'],['رمز التحقق لا يصل','راجع الرقم ومفتاح الدولة وانتظر المدة الظاهرة، ثم جرّب إعادة الإرسال. لا تشارك الرمز مع أحد.']]),tip='أرسل للدعم: الدور، اسم الأكاديمية، الشاشة والخطوة، وقت المشكلة، نوع الجهاز وإصدار التطبيق، وصورة تخفي بيانات اللاعبين. لا ترسل كلمات المرور أو رمز التحقق.')
add('ابدأ بأكاديمية واحدة… ثم توسّع','Hagzz / تهيئة واضحة وتجربة قابلة للمراجعة', '<div class="closing"><h1>فريقك جاهز.<br>بياناتك مرتّبة.<br><em>والخطوة التالية واضحة.</em></h1><p>ابدأ بالإعداد، نفّذ تجربة تشغيل، ثم ادعُ اللاعبين وأولياء الأمور إلى النسخة المعتمدة.</p></div>'+cards([('لوحة الشركاء','<a href="https://partner.hagzz.el7lm.com/partner/login">فتح لوحة الشركاء</a>'),('تطبيق العملاء','<a href="https://play.google.com/store/apps/details?id=com.unlimitedhagzz.hagzz">فتح Google Play</a>')])+ '<aside><b>التواصل والتفعيل</b><p>لطلب تفعيل الأكاديمية وروابط Hagzz Partner وتفاصيل المنحة: <a href="https://wa.me/97470542458"><span dir="ltr">+974 7054 2458</span></a>. الأسعار الأساسية منشورة في <a href="https://hagzz.el7lm.com/pricing.html">صفحة الباقات</a>؛ يوضح عرض المنحة الخصومات والشهور المجانية المطبقة.</p></aside><p class="small">هذه النسخة تغطي الأكاديميات. أدلة الجيم والمراكز الصحية، ثم الملاعب والمرافق الرياضية، تُعد في مراحل مستقلة. © Hagzz 2026.</p>')
add('منحة التحول الرقمي للقطاع الرياضي','من Hagzz وواحة قطر للعلوم والتكنولوجيا', '<div class="closing"><h1>فرصة لكل أكاديمية.<br><em>مهما كان حجمها.</em></h1><p>دعم التحول الرقمي في القطاع الرياضي في قطر من خلال خصومات وشهور مجانية للأكاديميات دون تمييز بحسب الحجم.</p></div>'+cards([('ما الذي تستند إليه الأسعار؟','الأسعار الأساسية في صفحة الباقات على موقع Hagzz. يحدد العرض المعتمد الخصم والشهور المجانية وما يشمله التفعيل.'),('كيف تبدأ؟','تواصل مع فريق التهيئة، وعرّف بأكاديميتك واحتياجك، ثم استلم عرضك وبيانات التفعيل وروابط التطبيقات.')])+ '<div class="contact"><img src="assets/contact-qr.svg"><div><h3>تواصل لطلب المنحة والتفعيل</h3><a href="https://wa.me/97470542458" dir="ltr">+974 7054 2458</a><p><a href="https://hagzz.el7lm.com/pricing.html">عرض الباقات الأساسية</a></p></div></div><p class="small">لا يحدد هذا الدليل نسبة خصم أو عدد أشهر مجانية موحّدًا. تفاصيل الاستحقاق ونطاق الخدمة تعتمد في العرض المرسل للأكاديمية.</p>')
